import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './page/Login';
// Import thêm các trang khác của bạn vào đây (ví dụ mẫu bên dưới)
// import SubjectList from './pages/SubjectList'; 
// import Admin from './pages/Admin';

function App() {
  return (
    <Router>
      <Routes>
        {/* 1. Trang Đăng nhập */}
        <Route path="/login" element={<Login />} />

        {/* 2. Trang danh sách môn học / syllabus sau khi đăng nhập thành công */}
        {/* <Route path="/subject" element={<SubjectList />} /> */}
        {/* <Route path="/syllabus" element={<SubjectList />} /> */}

        {/* 3. Trang Quản trị (Admin) nếu có */}
        {/* <Route path="/admin" element={<Admin />} /> */}

        {/* 4. Yêu cầu: Root path (/) tự động redirect về /login */}
        <Route path="/" element={<Navigate to="/login" replace />} />

        {/* 5. Yêu cầu: Mọi đường dẫn không hợp lệ (*) tự động redirect về /login */}
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </Router>
  );
}

export default App;
